def bench_table():
    rows_ = bench_rows()
    if not rows_: return "<p class='note'>no benchmark results yet</p>"
    p_ = BENCH["parent"]
    AL = {"00": "0", "01": "0", "02": "1.0", "03": "1.0", "04": "0.1", "05": "0.25", "06": "0.5"}
    out = [f"<tr><th>parent</th><td>-</td><td>-</td><td>-</td><td>{p_['ifeval_ps']:.3f}</td><td>-</td>"
           f"<td>{p_['mgsm']:.3f}</td><td>-</td><td>{p_['gmmlu']:.3f}</td><td>-</td></tr>"]
    for tot, arm, ep, i, m, g in rows_:
        k = f"arm{arm}_ep{ep}"; v = BENCH[k]
        cls = " class=hi" if i < -3 else ""
        out.append(f"<tr><th>arm {arm} ep{ep}</th><td>{LRV[arm]:.0e}</td><td>{AL[arm]}</td>"
                   f"<td>{tot:.2e}</td>"
                   f"<td>{v['ifeval_ps']:.3f}</td><td{cls}>{i:+.1f}</td>"
                   f"<td>{v['mgsm']:.3f}</td><td>{m:+.1f}</td>"
                   f"<td>{v['gmmlu']:.3f}</td><td>{g:+.1f}</td></tr>")
